mapper.select:
select
ub.*,
c.name as categoryName
from user_bill ub
left join category c on ub.category_id = c.id
where ub.user_id = #{userId}

    and year(ub.create_time) = #{year}


    and month(ub.create_time) = #{month}


    and day(ub.create_time) = #{day}

order by ub.create_time desc

select
    sum(case when type = 1 then user_bill.amount else 0 end) as income,
    sum(case when type = 2 then user_bill.amount else 0 end) as expense,
    sum(case when type = 3 then user_bill.amount else 0 end) as transfer
from user_bill
where year(create_time) = #{year}
    and month(create_time) = #{month}
    and user_id = #{userId}

        and day(create_time) = #{day}

SELECT c.name AS name, SUM(b.amount) AS value, COUNT(*) AS bill_count FROM user_bill b LEFT JOIN category c ON b.category_id = c.id
b.user_id = #{id}
AND b.type = #{type}
AND DATE_FORMAT(b.create_time, '%Y') = #{timeValue}
AND DATE_FORMAT(b.create_time, '%Y-%m') = #{timeValue}
AND DATE_FORMAT(b.create_time, '%Y-%m-%d') = #{timeValue}
GROUP BY c.id, c.name ORDER BY value DESC

